
const { DataTypes } = require("sequelize");
const sequelize = require("../config/database");

// ======================================================
// Medicine Model
// ======================================================
//
// Catalog entry for each medicine. Stock is tracked per
// batch (see Batch model), not on this table — this row
// only holds the medicine's identity and metadata.
//
// `reorderLevel` is the threshold below which a low-stock
// alert is generated by the inventory system.
// ======================================================

const Medicine = sequelize.define(
  "Medicine",
  {
    id: {
      type: DataTypes.INTEGER,
      autoIncrement: true,
      primaryKey: true
    },

    name: {
      type: DataTypes.STRING(150),
      allowNull: false
    },

    genericName: {
      type: DataTypes.STRING(150),
      allowNull: true
    },

    brandName: {
      type: DataTypes.STRING(150),
      allowNull: true
    },

    dosageForm: {
      type: DataTypes.STRING(50),
      allowNull: false
    },

    strength: {
      type: DataTypes.STRING(50),
      allowNull: true
    },

    description: {
      type: DataTypes.TEXT,
      allowNull: true
    },

    imageUrl: {
      type: DataTypes.STRING(2048),
      allowNull: true,
      validate: {
        isUrl: {
          msg: "Please provide a valid image URL."
        }
      }
    },

    sku: {
      type: DataTypes.STRING(100),
      allowNull: false,
      unique: true
    },

    barcode: {
      type: DataTypes.STRING(100),
      allowNull: true,
      unique: true
    },

    reorderLevel: {
      type: DataTypes.INTEGER,
      allowNull: false,
      defaultValue: 10
    },

    isPrescriptionRequired: {
      type: DataTypes.BOOLEAN,
      allowNull: false,
      defaultValue: false
    },

    isActive: {
      type: DataTypes.BOOLEAN,
      allowNull: false,
      defaultValue: true
    },

    categoryId: {
      type: DataTypes.INTEGER,
      allowNull: false,
      references: {
        model: "categories",
        key: "id"
      }
    }
  },
  {
    tableName: "medicines",
    timestamps: true
  }
);

module.exports = Medicine;